      final notions = notionIdsOf(exercise);
      final items = notions.map((n) => progress.progressFor(n)).toList();

      final anyOverdue =
          items.any((item) => item.isOverdue(effectiveToday));
      final anyNew =
          items.any((item) => item.state == LearningItemState.newItem);
      final anyEligible =
          items.any((item) => item.isEligibleForReview(effectiveToday));

      if (anyOverdue) {
        overdue.add(exercise);
      } else if (anyNew) {
        newItems.add(exercise);
      } else if (anyEligible) {
        eligible.add(exercise);
      } else {
        ineligible.add(exercise);
      }
    }

    _addFromBucketMulti(
      overdue,
      selected,
      usedNotions,
      notionIdsOf,
      count,
      generator,
    );
    _addFromBucketMulti(
      eligible,
      selected,
      usedNotions,
      notionIdsOf,
      count,
      generator,
    );
    _addFromBucketMulti(
      newItems,
      selected,
      usedNotions,
      notionIdsOf,
      count,
      generator,
    );
    _addFromBucketMulti(
